import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第62章 目标分歧","description":"","frontmatter":{},"headers":[],"relativePath":"第62章_目标分歧.md","filePath":"第62章_目标分歧.md"}'),r={name:"第62章_目标分歧.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第62章-目标分歧" tabindex="-1">第62章 目标分歧 <a class="header-anchor" href="#第62章-目标分歧" aria-label="Permalink to &quot;第62章 目标分歧&quot;">​</a></h1><p>（她的视角）那张写着想去的地方的纸片，一直在她手里折着。</p><p>叶老师站在讲台上，手里捏着一叠纸片，笑容温和。</p><p>“想一想心里最想去的地方。”她把纸片放在讲桌上。“写下来，折好，交给我。等潮水涨起来，我再还给你们看。”</p><p>教室里静了一会儿，随后响起低低的讨论声，椅子轻晃，纸页翻动。</p><p>我握着笔，笔杆被手心焐热。窗外传来海潮声，一下，又一下。空气里有阳光晒过棉布的味道，还有淡淡的皂香。</p><p>林小满凑过来，胳膊碰碰我，眼睛亮亮的。</p><p>“你想好了吗。”她小声问，呼吸里带着海盐糖的甜香。“我心里乱糟糟的，像被风吹散的沙。”</p><p>我摇头，笔尖在纸上点出一个小圆点。</p><p>“有点想法，又不敢落笔。”我说。“怕写下来，就变重了。”</p><p>她还要再问，叶老师轻轻敲了敲讲桌，大家便安静下来。我把空白的纸片夹进书里，指尖有些凉。</p><p>我把那张纸对折又展开，折痕在指腹下薄薄隆起。我用指甲顺着折痕来回刮，纸面发出细细的沙声，边缘被我摩得起了毛。林小满递来一块橡皮，我摇头，只把纸片压进笔记本最里层，夹在写满诗抄的页面之间。纸页合上时很轻，像合上一盏没点亮的灯。风从窗缝溜进来，吹得我手背凉凉的，我把手缩进袖口，闻到袖口残留的淡淡皂香，还有粉笔灰的涩味。</p><p>何晓从前排传来一张小纸条，上面只写了一句，别怕，慢慢写。她字迹圆润，墨香还新鲜。我把纸条对折，轻轻按在掌心，心里松了一小块，又紧回去。那年借址上课时，我们曾坐在同一间旧机房里听海潮录音，她说潮水会自己找方向，我当时点头，如今潮水真的来了，却要往两个方向走。</p><p>雾山大学，是雾山市最好的学校，听说图书馆的窗能看见海。沈聿提过好多次，每次提起，眼睛里都有光。</p><p>下课后，我去走廊透气。栏杆被太阳晒得温热，手扶上去很舒服。远处的海面亮闪闪的，风扑在脸上，带着咸味，睫毛被吹得轻颤。</p><p>沈聿在楼梯口等我，手里拿着一瓶温水，瓶壁上凝着细细的水珠。</p><p>“给你。”他把水递过来，指尖碰到我的手背，暖暖的。“看你整节课没写，笔都快被你点破了。”</p><p>我接过水，喝了一小口，温热的水滑进喉咙，身上松快了些。</p><p>“你写了吗。”我问。</p><p>“写了。”他点头，嘴角翘起来。“雾山大学。我想了很久，不改了。”</p><p>他的语气很稳，像潮水拍岸，一下是一下。</p><p>我低头看着栏杆，指腹沿着浅浅的纹路慢慢划过去。</p><p>“我还没写。”我说得很轻。</p><p>“慢慢想。”他靠在栏杆上，侧头看我，头发被风吹得微乱。“不过我猜，你也会写雾山。我们说好的，一起往高处走。”</p><p>我心里一紧，抬头看他。他的眼睛映着海的光，坦荡又热切。</p><p>我把温水瓶抱在怀里，用掌心一圈圈焐着。瓶壁的水珠蹭到手腕，凉凉滑下去。我低声说，写之前我把窗台的纸星星罐晃了晃，听见星星轻碰玻璃的声音，忽然就想起那天在南雾中学操场，你说一起往高处走，我晃着钥匙上的小铃铛说好。那时我以为高处是一条路，现在才发现，高处有两片海。</p><p>“我喜欢南州。”我说。</p><p>风大了一点，吹得衣角翻起来，发出轻响。</p><p>他愣了一下，眉心微微蹙起。</p><p>“南州？”他重复，声音低了些。“那边远，路也不熟。你怎么会想去那里。”</p><p>“我喜欢那里的传播课。”我说，指尖收紧，瓶身被捏得轻轻响。“何晓姐姐提过，南州靠海，风自由，故事多。我想去听更多的潮声，写更多的人。”</p><p>他沉默几秒，远处的潮声衬得这沉默有些长。</p><p>“雾山也有很好的文字课。”他说，语速比平时快，带着一点急。“而且离南雾县近，宋阿婆身子弱，陈默和顾远也都想冲雾山。我们在一起，彼此有个照应，不好吗。”</p><p>“我知道。”我咬了咬唇，嘴里泛起海盐糖留下的咸甜。“我也舍不得你们。只是每次闭眼，我看见的都是南边的海，雾散开，船进港，灯一盏盏亮起来。我想站在那里，把这些记下来。”</p><p>“那我呢。”他问，声音轻下去，像怕惊动什么。“我们说好一起的。你去南，我在雾山，路就岔开了。”</p><p>我的鼻子一酸，眼睛有些热。风吹过来，眼角凉凉的。</p><p>“我不想和你分开。”我说，嗓子发紧。“可我也不想骗自己。写下雾山，我的手会抖。”</p><p>他伸出手，想碰碰我的发顶，又在半空停住，最后落在栏杆上，指节微微发白。</p><p>“是我太急了。”他低声说。“我以为目标一致，就能一直并肩。没想过你心里装着另一片海。”</p><p>这时陈默跑过来，手里举着两颗纸星星，彩纸在阳光下闪着光。</p><p>“我写完啦，雾山。”他笑着，把星星塞进我手心。“送你两颗，保佑你落笔有神。反正不管去哪，咱们的心都连着。”</p><p>纸角扎着掌心，微微疼，却很真实。顾远抱着旧磁带机跟在后面，手指在按键上摩挲，发出咔哒的轻响，朝我笑了笑。</p><p>晚自习前，天色暗下来，海风转凉。教室的灯一盏盏亮起，暖黄的光落在桌面上。</p><p>林小满坐到我身边，剥开一颗海盐糖塞进我嘴里。</p><p>“含着，心里不慌。”她身上有淡淡的洗衣香。“南州的事，顾远说了。你别怕，我支持你。只是沈聿那边，你们得说开，别憋着。”</p><p>糖在舌尖化开，先咸后甜，喉咙里暖暖的。我点头，把空白纸片铺在桌上，纸面被灯光照得微微透。</p><p>放学后，我和沈聿约在操场边见。夜风凉凉的，吹得矮树叶子沙沙响。路灯晕开柔光，雾气在光里缓缓流动。</p><p>他把旧磁带机放在台阶上，按下播放键。磁带转动，发出沙沙声，随后是海潮的录音，一层层涌上来，又退下去，还有他低低的哼唱，混在潮声里。</p><p>“上次在海边录的。”他看着地面，睫毛投出小小的影。“本来想等你写完雾山，就送给你，当作约定的信物。”</p><p>我的心狠狠一跳，指尖发凉。</p><p>“沈聿，我不骗你。”我说，眼泪落在手背上，温热的，很快被风吹凉。“我若为了留下而留下，以后每次听见南边的潮声，都会遗憾。到那时，我怕你怪我，我也怪自己。”</p><p>他沉默很久，久到一片叶子轻轻落在台阶上。</p><p>“给我一点时间。”他终于开口，把磁带机塞进我怀里。机身还带着他的体温，暖暖的。“这盘带子，你先收着。路岔开的事，我们都再想想。也许雾和海之间，还有第三条路。”</p><p>我抱紧磁带机，金属边角硌着掌心，心跳得厉害。他转身走进雾里，背影被灯光拉长，很快变淡。</p><p>回到宿舍，瓶里的纸星星轻轻晃着，发出细碎的响。窗外潮声阵阵，推上来，又退下去。</p><p>我把磁带机放在书桌上，用干绒布把按键一个个擦干净。塑料壳被我焐热，指尖有点薄汗。我按下空转，让齿轮轻轻空转几圈，听见细细的咔哒声，又松开。我倒了小半杯热水捧着喝，热气熏得鼻尖发红，水有点烫，舌尖轻轻麻了一下。我把那张空白纸片重新抽出来，放在台灯下，灯光把纸照得透亮，纤维的纹路都看得见。我还是没写，只在纸角点了一个更小的点，像给自己留一个迟到的记号。</p><p>手机轻轻震了一下，是他发来的短讯，只有短短一句，明早天台见，有话对你说。</p><p>我盯着那行字，指尖发烫。窗外的雾，又浓了起来。</p>',58)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
